export class AgentCoordinator {
  async dispatchRoutine(agentId: string, task: TaskSpec) {
    const agent = this.registry.get(agentId);
    if (agent.state !== 'IDLE' || !agent.batteryOk()) return this.reassignTask(task);
    await agent.executePlan(task.plan);
  }
}

export function evaluateCriteria(candidate: PatientProfile, trial: TrialSpec): MatchResult {
  const passesInclusion = trial.inclusions.every(rule => rule.validate(candidate));
  const passesExclusion = !trial.exclusions.some(rule => rule.validate(candidate));
  return { isEligible: passesInclusion && passesExclusion, timestamp: Date.now() };
}

export async function evaluateCrisisSignal(payload) {
  const urgencyScore = await nlpPipeline.predict(payload.text);
  if (urgencyScore > 0.85) {
    const geo = extractNamedEntities(payload.text);
    return dispatchEmergencyBroadcast({ ...payload, urgencyScore, geo });
  }
}

function filterZenArticles(articles, options) {
  const sanitized = articles.filter(a => !isClickbait(a.title) && a.urlToImage);
  return deduplicateByHeadlineSimilarity(sanitized, options.threshold);
}
